#include <stdint.h>
#include "stm32f411xe.h"
#include "stm32f4xx.h"

// Variable global: guarda en que paso de la secuencia de LEDs vamos
// 0 = verde, 1 = amarillo, 2 = rojo
uint8_t estado_actual = 0;

int main(void)
{
    /* =========================================================================
     * PASO 1: HABILITAR RELOJES DE GPIOB (RCC->AHB1ENR)
     * Manual de Referencia RM0383 - Seccion 6.3.9
     * ========================================================================= */
    RCC->AHB1ENR &= ~RCC_AHB1ENR_GPIOBEN; // Limpiando la posición
    RCC->AHB1ENR |=  RCC_AHB1ENR_GPIOBEN; // Habilitar señal de reloj para GPIOB (Bit 1)

    /* =========================================================================
     * PASO 2: CONFIGURAR PB8, PB9 Y PB6 COMO SALIDA PUSH-PULL, BAJA VELOCIDAD
     * (Sin resistencias internas: las resistencias ya están en el protoboard)
     * Manual de Referencia RM0383 - Seccion 8.4
     * ========================================================================= */

    /* Verde (PB8) */
    GPIOB->MODER   &= ~(GPIO_MODER_MODE8);     // Limpiar bits de modo para PB8
    GPIOB->MODER   |=  (GPIO_MODER_MODE8_0);   // Configurar PB8 como salida (general purpose output)
    GPIOB->OTYPER  &= ~(GPIO_OTYPER_OT8);      // Configurar PB8 como salida push-pull
    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED8); // Configurar PB8 como baja velocidad
    GPIOB->PUPDR   &= ~(GPIO_PUPDR_PUPD8);     // Configurar PB8 sin pull-up/pull-down
    GPIOB->ODR     &= ~(GPIO_ODR_OD8);         // Inicializar PB8 en bajo

    /* Amarillo (PB9) */
    GPIOB->MODER   &= ~(GPIO_MODER_MODE9);     // Limpiar bits de modo para PB9
    GPIOB->MODER   |=  (GPIO_MODER_MODE9_0);   // Configurar PB9 como salida (general purpose output)
    GPIOB->OTYPER  &= ~(GPIO_OTYPER_OT9);      // Configurar PB9 como salida push-pull
    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED9); // Configurar PB9 como baja velocidad
    GPIOB->PUPDR   &= ~(GPIO_PUPDR_PUPD9);     // Configurar PB9 sin pull-up/pull-down
    GPIOB->ODR     &= ~(GPIO_ODR_OD9);         // Inicializar PB9 en bajo

    /* Rojo (PB6) */
    GPIOB->MODER   &= ~(GPIO_MODER_MODE6);     // Limpiar bits de modo para PB6
    GPIOB->MODER   |=  (GPIO_MODER_MODE6_0);   // Configurar PB6 como salida (general purpose output)
    GPIOB->OTYPER  &= ~(GPIO_OTYPER_OT6);      // Configurar PB6 como salida push-pull
    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED6); // Configurar PB6 como baja velocidad
    GPIOB->PUPDR   &= ~(GPIO_PUPDR_PUPD6);     // Configurar PB6 sin pull-up/pull-down
    GPIOB->ODR     &= ~(GPIO_ODR_OD6);         // Inicializar PB6 en bajo

    /* =========================================================================
     * PASO 3: CONFIGURAR EL SYSTICK PARA QUE CUENTE 1000 ms, SIN INTERRUPCIONES
     * (Core Cortex-M4 - core_cm4.h)
     * El SysTick es un contador de 24 bits que viene dentro del nucleo ARM
     * (no es un periferico de ST). Cuenta hacia ABAJO desde LOAD hasta 0 y,
     * cuando llega a 0, levanta la bandera COUNTFLAG y se recarga solo.
     * ========================================================================= */

    // 16 MHz = 16.000.000 pulsos por segundo. Se resta 1 porque el contador
    // cuenta desde LOAD hasta 0 (ambos incluidos), o sea LOAD+1 pulsos.
    // El maximo posible es 16.777.215 (24 bits), asi que cabe.
    SysTick->LOAD = 16000000 - 1;                    // Valor de recarga: define el periodo de 1 s

    // Escribir cualquier valor en VAL lo pone en 0 y tambien borra COUNTFLAG.
    SysTick->VAL  = 0;                               // Reinicia el contador actual

    // TICKINT (bit 1): si vale 1, al llegar a 0 se genera una interrupcion.
    // Lo dejamos en 0 porque revisamos la bandera por polling en el while(1).
    SysTick->CTRL &= ~(SysTick_CTRL_TICKINT_Msk);    // Deshabilitar interrupciones del SysTick

    // CLKSOURCE (bit 2): 0 = reloj del procesador / 8, 1 = reloj del procesador directo.
    // Con el HSI de 16 MHz, eso da 16 MHz exactos.
    SysTick->CTRL &= ~(SysTick_CTRL_CLKSOURCE_Msk);  // Limpiar la posicion
    SysTick->CTRL |=  (SysTick_CTRL_CLKSOURCE_Msk);  // Seleccionar reloj del procesador (16 MHz)

    // ENABLE (bit 0): arranca el conteo. Se activa al final, ya con todo configurado.
    SysTick->CTRL &= ~SysTick_CTRL_ENABLE_Msk;       // Limpiar la posicion
    SysTick->CTRL |=  SysTick_CTRL_ENABLE_Msk;       // Habilitar el contador del SysTick

    /* =========================================================================
     * BUCLE PRINCIPAL (SUPER LOOP)
     * Cada vez que pasa 1 s se cambia de LED: verde -> amarillo -> rojo -> verde...
     * ========================================================================= */
    while (1)
    {
        // COUNTFLAG (bit 16) pasa a 1 cuando el contador llego a 0 (paso 1 s).
        // Se borra sola al leer el registro CTRL, no hace falta limpiarla a mano.
        if (SysTick->CTRL & SysTick_CTRL_COUNTFLAG_Msk)
        {
            // Solo un LED encendido a la vez: se prende el que toca y se apagan los otros dos.
            switch (estado_actual)
            {
                case 0: // Turno del LED verde
                    GPIOB->ODR |=  (GPIO_ODR_OD8);   // Encender LED verde (PB8 = 1)
                    GPIOB->ODR &= ~(GPIO_ODR_OD9);   // Apagar LED amarillo (PB9 = 0)
                    GPIOB->ODR &= ~(GPIO_ODR_OD6);   // Apagar LED rojo (PB6 = 0)
                    estado_actual++;                 // Pasar al siguiente estado (amarillo)
                    break;

                case 1: // Turno del LED amarillo
                    GPIOB->ODR |=  (GPIO_ODR_OD9);   // Encender LED amarillo (PB9 = 1)
                    GPIOB->ODR &= ~(GPIO_ODR_OD8);   // Apagar LED verde (PB8 = 0)
                    GPIOB->ODR &= ~(GPIO_ODR_OD6);   // Apagar LED rojo (PB6 = 0)
                    estado_actual++;                 // Pasar al siguiente estado (rojo)
                    break;

                case 2: // Turno del LED rojo
                    GPIOB->ODR &= ~(GPIO_ODR_OD8);   // Apagar LED verde (PB8 = 0)
                    GPIOB->ODR &= ~(GPIO_ODR_OD9);   // Apagar LED amarillo (PB9 = 0)
                    GPIOB->ODR |=  (GPIO_ODR_OD6);   // Encender LED rojo (PB6 = 1)
                    estado_actual = 0;               // Volver al inicio de la secuencia (verde)
                    break;

                default: // Seguridad: si la variable toma un valor inesperado, se reinicia la secuencia
                    estado_actual = 0;
                    break;
            }
        }
    }
    return 0;
}